        title = row.get("Title", "").strip()
        if not title:
            continue
        authors = row.get("Authors", "").strip()
        isbn = norm_isbn(row.get("ISBN", ""))
        tf, ts = title_key(title)
        a1 = first_author(authors)
        bf_rows.append({
            "title": title, "authors": authors, "isbn": isbn,
            "title_full": tf, "title_short": ts, "author1": a1
        })

matched = []
unmatched = []

for b in bf_rows:
