    reason = None
    if b["isbn"] and b["isbn"] in calibre_isbn:
        hit = calibre_isbn[b["isbn"]]
        reason = "isbn"
    elif b["title_full"] in calibre_full:
        cands = calibre_full[b["title_full"]]
